package service

import (
	"fmt"
	"sync"
)

// User represents a user in the system
type User struct {
	ID    string `json:"id"`
	Name  string `json:"name"`
	Email string `json:"email"`
}

var (
	users  = make(map[string]User)
	mutex  sync.RWMutex
	nextID = 1
)

func GetAllUsers() []User {
	mutex.RLock()
	defer mutex.RUnlock()
	var list []User
	for _, u := range users {
		list = append(list, u)
	}
	return list
}

func CreateUser(user User) User {
	mutex.Lock()
	defer mutex.Unlock()
	user.ID = fmt.Sprintf("%d", nextID)
	nextID++
	users[user.ID] = user
	return user
}

func GetUserByID(id string) (User, bool) {
	mutex.RLock()
	defer mutex.RUnlock()
	user, ok := users[id]
	return user, ok
}

package api

import (
	"encoding/json"
	"net/http"
	"experiment/internal/service"
)

// UserHandlers provides http handlers for user-related requests
type UserHandlers struct {
	// No explicit service field needed as service functions are package-level
}

func (h *UserHandlers) HandleUsers(w http.ResponseWriter, r *http.Request) {
	switch r.Method {
	case http.MethodGet:
		h.HandleGetUsers(w, r)
	case http.MethodPost:
		h.HandlePostUsers(w, r)
	default:
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
	}
}

func (h *UserHandlers) HandleGetUsers(w http.ResponseWriter, r *http.Request) {
	list := service.GetAllUsers()
	json.NewEncoder(w).Encode(list)
}

func (h *UserHandlers) HandlePostUsers(w http.ResponseWriter, r *http.Request) {
	var u service.User
	if err := json.NewDecoder(r.Body).Decode(&u); err != nil {
		http.Error(w, err.Error(), http.StatusBadRequest)
		return
	}
	u = service.CreateUser(u)
	w.WriteHeader(http.StatusCreated)
	json.NewEncoder(w).Encode(u)
}

func (h *UserHandlers) HandleUserByID(w http.ResponseWriter, r *http.Request) {
	id := r.URL.Path[len("/users/"):]
	switch r.Method {
	case http.MethodGet:
		h.HandleGetUserByID(w, r, id)
	default:
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
	}
}

func (h *UserHandlers) HandleGetUserByID(w http.ResponseWriter, r *http.Request, id string) {
	u, ok := service.GetUserByID(id)
	if !ok {
		http.NotFound(w, r)
		return
	}
	json.NewEncoder(w).Encode(u)
}

package main

import (
	"log"
	"net/http"

	"experiment/internal/api"
)

func main() {
	userHandlers := &api.UserHandlers{}

	http.HandleFunc("/users", userHandlers.HandleUsers)
	http.HandleFunc("/users/", userHandlers.HandleUserByID)

	log.Println("Server starting on :8080...")
	if err := http.ListenAndServe(":8080", nil); err != nil {
		log.Fatal(err)
	}
}

package service

import (
	"sync"

	"github.com/google/uuid"
)

// User represents a user in the system
type User struct {
	ID    string `json:"id"`
	Name  string `json:"name"`
	Email string `json:"email"`
}

var (
	users = make(map[string]User)
	mutex sync.RWMutex
	// nextID is no longer needed as we'll use UUIDs
)

func GetAllUsers() []User {
	mutex.RLock()
	defer mutex.RUnlock()
	var list []User
	for _, u := range users {
		list = append(list, u)
	}
	return list
}

func CreateUser(user User) User {
	mutex.Lock()
	defer mutex.Unlock()
	user.ID = uuid.New().String() // Use UUID for ID generation
	users[user.ID] = user
	return user
}

func GetUserByID(id string) (User, bool) {
	mutex.RLock()
	defer mutex.RUnlock()
	user, ok := users[id]
	return user, ok
}

package main

import (
	"bytes"
	"encoding/json"
	"net/http"
	"net/http/httptest"
	"testing"

	"experiment/internal/api"
	"experiment/internal/service" // Import service to access User struct if needed for assertions
)

func TestUserAPI(t *testing.T) {
	userHandlers := &api.UserHandlers{}

	// Test POST /users
	t.Run("CreateUser", func(t *testing.T) {
		newUser := service.User{Name: "John Doe", Email: "john@example.com"}
		body, _ := json.Marshal(newUser)
		req := httptest.NewRequest(http.MethodPost, "/users", bytes.NewBuffer(body))
		rec := httptest.NewRecorder()

		userHandlers.HandleUsers(rec, req)

		if rec.Code != http.StatusCreated {
			t.Errorf("Expected status %d, got %d", http.StatusCreated, rec.Code)
		}

		var createdUser service.User
		json.NewDecoder(rec.Body).Decode(&createdUser)
		if createdUser.ID == "" {
			t.Error("Expected user ID to be generated, got empty")
		}
		if createdUser.Name != newUser.Name || createdUser.Email != newUser.Email {
			t.Errorf("Expected user %v, got %v", newUser, createdUser)
		}
	})

	// Test GET /users
	t.Run("GetAllUsers", func(t *testing.T) {
		req := httptest.NewRequest(http.MethodGet, "/users", nil)
		rec := httptest.NewRecorder()

		userHandlers.HandleUsers(rec, req)

		if rec.Code != http.StatusOK {
			t.Errorf("Expected status %d, got %d", http.StatusOK, rec.Code)
		}

		var users []service.User
		json.NewDecoder(rec.Body).Decode(&users)
		if len(users) != 1 { // Should be 1 user from the previous test
			t.Errorf("Expected 1 user, got %d", len(users))
		}
	})

	// Test GET /users/{id}
	t.Run("GetUserByID", func(t *testing.T) {
		// First, create a user to get an ID
		newUser := service.User{Name: "Jane Doe", Email: "jane@example.com"}
		body, _ := json.Marshal(newUser)
		postReq := httptest.NewRequest(http.MethodPost, "/users", bytes.NewBuffer(body))
		postRec := httptest.NewRecorder()
		userHandlers.HandleUsers(postRec, postReq)
		var createdUser service.User
		json.NewDecoder(postRec.Body).Decode(&createdUser)
		userID := createdUser.ID

		req := httptest.NewRequest(http.MethodGet, "/users/"+userID, nil)
		rec := httptest.NewRecorder()

		userHandlers.HandleUserByID(rec, req)

		if rec.Code != http.StatusOK {
			t.Errorf("Expected status %d, got %d", http.StatusOK, rec.Code)
		}

		var retrievedUser service.User
		json.NewDecoder(rec.Body).Decode(&retrievedUser)
		if retrievedUser.ID != userID || retrievedUser.Name != newUser.Name {
			t.Errorf("Expected user %v, got %v", createdUser, retrievedUser)
		}
	})

	// Test GET /users/{id} not found
	t.Run("GetUserByIDNotFound", func(t *testing.T) {
		nonExistentID := "non-existent-id"
		req := httptest.NewRequest(http.MethodGet, "/users/"+nonExistentID, nil)
		rec := httptest.NewRecorder()

		userHandlers.HandleUserByID(rec, req)

		if rec.Code != http.StatusNotFound {
			t.Errorf("Expected status %d, got %d", http.StatusNotFound, rec.Code)
		}
	})
}
